  function openBlind(){selectSkill('blindfold');setTimeout(()=>$('#blindChallenge')?.classList.add('open'),20)}
  function setupBlind(){
 const start=$('#blindStart'); if(!start)return;
 const files='abcdefgh', ranks='12345678';
 const knightMoves=[[1,2],[2,1],[-1,2],[-2,1],[1,-2],[2,-1],[-1,-2],[-2,-1]];
 const legalKnight=(from)=>{const fx=files.indexOf(from[0]),fy=ranks.indexOf(from[1]),out=[];for(const [dx,dy] of knightMoves){const x=fx+dx,y=fy+dy;if(x>=0&&x<8&&y>=0&&y<8)out.push(files[x]+ranks[y])}return out};
 const randomPos=()=>files[Math.floor(Math.random()*8)]+ranks[Math.floor(Math.random()*8)];
 function makeChallenge(){
   let current=randomPos(),path=[current], hops=2+Math.floor(Math.random()*2);
   for(let i=0;i<hops;i++){const moves=legalKnight(current);current=moves[Math.floor(Math.random()*moves.length)];path.push(current)}
   const target=current;
   $('#mentalCoord').textContent=path.slice(0,-1).join(' → ')+' → ?';
   $('#mentalCard').dataset.answer=target;
   $('#blindPrompt').textContent=`Continue The Line Mentally. Where Does The Knight Land After The Final Move?`;
   const options=new Set([target]);
   while(options.size<4)options.add(randomPos());
   $('#blindOptions').innerHTML='';
   [...options].sort(()=>Math.random()-.5).forEach(square=>{
     const b=document.createElement('button');b.type='button';b.className='challenge-option';b.textContent=square;
     b.addEventListener('click',()=>{const correct=square===target;$$('.challenge-option',document).forEach(x=>x.classList.remove('correct','wrong'));b.classList.add(correct?'correct':'wrong');$('#blindResult').textContent=correct?`Correct — ${target}. You kept the position.`:'Not Quite. Rebuild The Line In Your Head And Try Again.';if(correct)toast('Blindfold Chess','Position Retained. ✦')});
     $('#blindOptions').appendChild(b);
   });
   $('#blindResult').textContent='The Sequence Stays Hidden. No Board Required.';
 }
 start.addEventListener('click',makeChallenge);makeChallenge();
}
  let cubeRunning=false,cubeStartAt=0,cubeRaf=0;function setupCube(){const start=$('#cubeStart'),cube=$('#cubeReal');if(!start||!cube)return;start.addEventListener('click',()=>{if(!cubeRunning){cubeRunning=true;cubeStartAt=performance.now();$('#cubeTime').textContent='0.00';$('#cubeStatus').textContent='Running';start.innerHTML='<span class="material-symbols-outlined">stop</span>Stop Timer';cube.classList.add('timing');cubeTick()}else{cubeRunning=false;cancelAnimationFrame(cubeRaf);cube.classList.remove('timing');$('#cubeStatus').textContent='Stopped';start.innerHTML='<span class="material-symbols-outlined">timer</span>Start Timer';toast('Solve Logged',`${$('#cubeTime').textContent}s — Now Look For The Pauses.`)}})}
