  function updateWH(){const r=wh.getBoundingClientRect();const total=Math.max(1,r.height-innerHeight);const startLead=innerHeight*(innerWidth<=720?.28:.18);const activeTravel=Math.max(1,total*(innerWidth<=720?.64:.78));const p=Math.max(0,Math.min(1,(-r.top+startLead)/activeTravel));ring.style.transform=`translate(-50%,-50%) scale(${.26+p*2.05}) rotate(${p*18}deg)`;core.style.transform=`translate(-50%,-50%) scale(${.08+p*1.45})`;bg.style.transform=`scale(${1.05+p*.16}) rotate(${p*5}deg)`;if(p>.52)ring.style.borderColor=`rgba(255,255,255,${.12+p*.42})`;}
  addEventListener('scroll',updateWH,{passive:true});updateWH();
